CREATE SCHEMA integration;
CREATE TABLE integration.services (id bigserial PRIMARY KEY, name varchar(255), shortname varchar(255), status integer, tenant_id varchar(255), created_at timestamp, updated_at timestamp, deleted_at timestamp);
CREATE TABLE integration.type_hook (LIKE integration.services INCLUDING DEFAULTS);
ALTER TABLE integration.type_hook ALTER COLUMN id DROP DEFAULT;
ALTER TABLE integration.type_hook ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE integration.type_hook ADD PRIMARY KEY (id);
CREATE TABLE integration.type_processing (LIKE integration.services INCLUDING DEFAULTS);
ALTER TABLE integration.type_processing ALTER COLUMN id DROP DEFAULT;
ALTER TABLE integration.type_processing ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE integration.type_processing ADD PRIMARY KEY (id);
CREATE TABLE integration.rules (id bigserial PRIMARY KEY, name varchar(255), shortname varchar(255), type_processing_id integer, val varchar(255), params json, status integer, tenant_id varchar(255), created_at timestamp, updated_at timestamp, deleted_at timestamp);
CREATE TABLE integration.webhooks (id bigserial PRIMARY KEY, name varchar(255), shortname varchar(255), service_id integer, type_hook_id integer, url varchar(255), rules_id jsonb, cnt integer, dat_last_run timestamp, params json, status integer, tenant_id varchar(255), created_at timestamp, updated_at timestamp, deleted_at timestamp);
CREATE TABLE integration.data (id bigserial PRIMARY KEY, name varchar(255), shortname varchar(255), webhook_id integer, service_id integer, raw text, src jsonb, data jsonb, progress_processing jsonb, status_processing integer, status integer, tenant_id varchar(255), created_at timestamp, updated_at timestamp, deleted_at timestamp);
